import itertools, functools
def pal(s): return s == s[::-1]
def lps(s): return max(k for k in range(len(s) + 1) for c in itertools.combinations(s, k) if pal(c))
def lcs(a, b):
    @functools.lru_cache(None)
    def f(i, j):
        if i == len(a) or j == len(b): return 0
        return 1 + f(i + 1, j + 1) if a[i] == b[j] else max(f(i + 1, j), f(i, j + 1))
    return f(0, 0)
def ins(s):
    seen = {s: 0}; todo = [s]
    for t in todo:
        if pal(t): return seen[t]
        if seen[t] >= len(s): continue
        for i in range(len(t) + 1):
            for ch in set(s):
                u = t[:i] + ch + t[i:]
                if u not in seen: seen[u] = seen[t] + 1; todo.append(u)
result = lps("abcda")

